import pandas as pd
import json
from pathlib import Path

# Carregar planilha
df = pd.read_excel('licitações.xlsx')

# Limpar e normalizar os numeros
def extract_num_ano(x):
    if pd.isna(x): return None
    import re
    m = re.search(r'(\d+)/(\d{4})', str(x))
    if m:
        return f"{m.group(1).zfill(5)}/{m.group(2)}"
    return None

df['num_normalizado'] = df['Nº Procedimento'].apply(extract_num_ano)

# Carregar JSONs do PNCP
pncp_records = []
for ano in [2023, 2024, 2025, 2026]:
    fpath = f'contratacoes_tce_pncp_{ano}.json'
    if Path(fpath).exists():
        with open(fpath, 'r', encoding='utf-8') as f:
            for item in json.load(f):
                num = item.get('numero_compra')
                if num:
                    pncp_records.append({
                        'num': num,
                        'ano': ano,
                        'fonte': f'PNCP_{ano}',
                        'valor': item.get('valor_estimado', 0)
                    })

# Carregar licitacoes_export.json (TCE)
if Path('licitacoes_export.json').exists():
    with open('licitacoes_export.json', 'r', encoding='utf-8') as f:
        for item in json.load(f):
            num = item.get('numero_licitacao')
            if num:
                # O TCE pode usar algo como "0001/2026"
                pncp_records.append({
                    'num': num,
                    'ano': item.get('ano_licitacao'),
                    'fonte': 'MURALIC',
                    'valor': item.get('valor_estimado', 0)
                })

