import urllib.request, ssl, json
ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

def fetch(url):
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0', 'Accept': 'application/json'})
    with urllib.request.urlopen(req, context=ctx, timeout=15) as r:
        return json.loads(r.read().decode('utf-8'))

for idug, nome in [(4, 'TJPI'), (2, 'CGJ-PI'), (1251, 'FERMOJUPI')]:
    offset = 0
    anos = {2024: 0, 2025: 0, 2026: 0, 'outros': 0}
    modalidades = {}

    # Vamos ler em blocos de 100 até achar anos anteriores a 2024
    parar = False
    while not parar:
        url = f'https://portal.tce.pi.gov.br/muralic/api/licitacoes?idug={idug}&offset={offset}&limit=100&expand=true'
        res = fetch(url)
        items = res.get('items', [])
        if not items:
            break
        for it in items:
            dt = it.get('dataCriacao') or ''
            ano = int(dt[:4]) if len(dt) >= 4 and dt[:4].isdigit() else 0
            if ano in anos:
                anos[ano] += 1
                mod = it.get('modalidade') or 'Nao informada'
                modalidades[mod] = modalidades.get(mod, 0) + 1
            else:
                anos['outros'] += 1
                if ano < 2024 and ano > 0:
                    parar = True
                    break
        offset += len(items)
        if len(items) < 100:
            break

    print(f'=== {nome} (UG {idug}) ===')
    print('  Anos:', anos)
    print('  Modalidades recentes:', modalidades)
