"import urllib.request, json, sys, time

sys.stdout.reconfigure(encoding='utf-8')
headers = {'User-Agent': 'Mozilla/5.0'}

mps = [
    {"sigla": "MPMA", "nome": "PGJ Maranhão", "cnpj": "05483912000185"},
    {"sigla": "MPBA", "nome": "PGJ Bahia", "cnpj": "04142491000166"},
    {"sigla": "MPRN", "nome": "PGJ Rio Grande do Norte", "cnpj": "08539710000104"},
    {"sigla": "MPPB", "nome": "PGJ Paraíba", "cnpj": "09284001000180"},
    {"sigla": "MPAL", "nome": "PGJ Alagoas", "cnpj": "12472734000152"},
    {"sigla": "MPSE", "nome": "PGJ Sergipe", "cnpj": "13168687000110"}
]

print("=== VERIFICAÇÃO COMPLETA: PREGÃO (6), DISPENSA (8) E INEXIGIBILIDADE (9) ===", flush=True)

for m in mps:
    sigla = m["sigla"]
    cnpj = m["cnpj"]
    resumo_mods = {}

    for ano in [2024, 2025, 2026]:
        for mod, mod_nome in [(6, "Pregao"), (8, "Dispensa"), (9, "Inex")]:
            url = f"https://pncp.gov.br/api/consulta/v1/contratacoes/publicacao?dataInicial={ano}0101&dataFinal={ano}1231&codigoModalidadeContratacao={mod}&cnpj={cnpj}&pagina=1&tamanhoPagina=10"
            tot = 0
            try:
                req = urllib.request.Request(url, headers=headers)
                with urllib.request.urlopen(req, timeout=8) as r:
                    d = json.loads(r.read().decode('utf-8'))
                    tot = d.get('totalRegistros', 0)
            except Exception:
                pass
            chave = f"{ano}_{mod_nome}"
            resumo_mods[chave] = tot
            time.sleep(1.0)

    print(f"[{sigla}] {m['nome']} ({cnpj}):", flush=True)
    for k, v in resumo_mods.items():
        if v > 0:
            print(f"    - {k}: {v} certames", flush=True)

print("\nVerificação completa concluída!", flush=True)
"

