"python -c "
import urllib.request, json
# Buscar texto 'Ministério Público' na Paraíba (uf=PB)
headers = {'User-Agent': 'Mozilla/5.0'}
for uf in ['PB', 'RN', 'AL', 'SE', 'BA']:
    url = f'https://pncp.gov.br/api/consulta/v1/contratacoes/publicacao?dataInicial=20240101&dataFinal=20241231&codigoModalidadeContratacao=8&uf={uf}&pagina=1&tamanhoPagina=10'
    try:
        req = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(req, timeout=10) as r:
            d = json.loads(r.read().decode('utf-8'))
            items = d.get('data', [])
            for it in items:
                org = it.get('orgaoEntidade', {})
                nome = org.get('razaoSocial', '')
                if 'MINISTERIO PUBLICO' in nome.upper() or 'PROCURADORIA' in nome.upper():
                    print(f'[{uf}] Achado: CNPJ {org.get(\"cnpj\")} - {nome}')
    except Exception as e:
        print(f'Erro {uf}:', e)
""

